    return f"OK: wrote {path} ({len(content)} bytes)"


def apply_patch(ctx, patch: str) -> str:
    # Many models (esp. OpenAI/Codex family) emit the "*** Begin Patch" envelope
    # rather than a git unified diff; support both.
    if "*** Begin Patch" in patch or "*** Update File:" in patch or "*** Add File:" in patch:
        return _apply_envelope(ctx, patch)
    with tempfile.NamedTemporaryFile("w", suffix=".patch", delete=False, encoding="utf-8", newline="") as f:
        f.write(patch if patch.endswith("\n") else patch + "\n")
        patch_path = f.name
    res = run(["git", "apply", "--whitespace=nowarn", patch_path], cwd=ctx.repo_path)
    if not res.ok:
        return f"ERROR: git apply failed:\n{res.combined()}"
    return "OK: patch applied"


