def _apply_envelope(ctx, patch: str) -> str:
    files: dict[str, list[str]] = {}
    adds: dict[str, list[str]] = {}
    cur = None
    bucket = None
    for line in patch.splitlines():
        if line.startswith("*** Update File:"):
            cur = line.split(":", 1)[1].strip()
            files.setdefault(cur, [])
            bucket = files[cur]
        elif line.startswith("*** Add File:"):
            cur = line.split(":", 1)[1].strip()
            adds.setdefault(cur, [])
            bucket = adds[cur]
        elif line.startswith("*** ") or line.startswith("@@"):
            continue
        elif bucket is not None:
            bucket.append(line)

    applied = []
    for path, content in adds.items():
        write_file(ctx, path, "\n".join(l[1:] if l[:1] == "+" else l for l in content))
        applied.append(path)
    for path, hunk in files.items():
        old = "\n".join(l[1:] for l in hunk if l[:1] in (" ", "-")).strip("\n")
        new = "\n".join(l[1:] for l in hunk if l[:1] in (" ", "+")).strip("\n")
        if not old:
            return f"ERROR: empty patch hunk for {path}"
        res = edit_file(ctx, path, old, new)
        if res.startswith("ERROR"):
            return f"ERROR applying hunk to {path}: {res}"
        applied.append(path)
    return f"OK: patch applied to {', '.join(applied)}" if applied else "ERROR: no file blocks in patch"

