import requests

from .base import LLMResponse, ToolCall


class OpenAICompatClient:
    """One client for any OpenAI-compatible chat-completions API (Groq, OpenAI, Ollama, ...)."""

    def __init__(self, provider: str, base_url: str, model: str, api_key: str | None,
                 temperature: float = 0.1, timeout: int = 240):
        self.provider = provider
        self.base_url = base_url.rstrip("/")
        self.model = model
        self.api_key = api_key
        self.temperature = temperature
        self.timeout = timeout

    def complete(self, system: str, messages: list[dict], tools: list[dict]) -> LLMResponse:
        payload = {
            "model": self.model,
            "messages": [{"role": "system", "content": system}] + messages,
            "tools": tools,
            "temperature": self.temperature,
        }
        headers = {"Content-Type": "application/json"}
        if self.api_key:
            headers["Authorization"] = f"Bearer {self.api_key}"

        data = self._post_with_retry(headers, payload)

        choice = data["choices"][0]["message"]
        usage = data.get("usage", {})
        calls = []
        for tc in choice.get("tool_calls") or []:
            fn = tc["function"]
            try:
                args = json.loads(fn["arguments"] or "{}")
            except json.JSONDecodeError:
                args = {"_raw": fn["arguments"]}
            calls.append(ToolCall(id=tc.get("id", fn["name"]), name=fn["name"], arguments=args))

        return LLMResponse(
            text=choice.get("content") or "",
            tool_calls=calls,
            input_tokens=usage.get("prompt_tokens", 0),
            output_tokens=usage.get("completion_tokens", 0),
        )

   text=choice.get("content") or "",
        tool_calls=calls,
        input_tokens=usage.get("prompt_tokens", 0),
        output_tokens=usage.get("completion_tokens", 0),
    )

def _post_with_retry(self, headers, payload, max_retries: int = 10) -> dict:
    url = f"{self.base_url}/chat/completions"
    for attempt in range(max_retries):
        try:
            resp = requests.post(url, headers=headers, data=json.dumps(payload),
                                 timeout=self.timeout)
        except (requests.Timeout, requests.ConnectionError):
            if attempt < max_retries - 1:
                time.sleep(5)
                continue
            raise
        if resp.status_code < 400:
            return resp.json()
        # Free tiers throttle on requests/tokens per minute; wait out the window and retry.
        is_rate = resp.status_code == 429 or (
            resp.status_code == 413 and "rate_limit" in resp.text.lower())
        if is_rate and attempt < max_retries - 1:
            time.sleep(self._retry_after(resp))
            continue
        # Llama-on-Groq sometimes emits tool calls as `<function=name{...}>` text,
        # which the API rejects. Salvage the call rather than failing the run.
        if resp.status_code == 400 and "tool_use_failed" in resp.text:
            salvaged = self._salvage_tool_call(resp.json())
            if salvaged is not None:
                return salvaged
        raise RuntimeError(f"{self.provider} API error {resp.status_code}: {resp.text[:400]}")
    raise RuntimeError(f"{self.provider} API: exhausted retries")

@staticmethod
def _salvage_tool_call(err_json: dict):
    gen = (err_js

error {resp.status_code}: {resp.text[:400]}")
        raise RuntimeError(f"{self.provider} API: exhausted retries")

    @staticmethod
    def _salvage_tool_call(err_json: dict):
        gen = (err_json.get("error", {}) or {}).get("failed_generation", "")
        if not gen:
            return None
        pat = re.compile(r"<function=([A-Za-z_]\w*)\s*(\{.*?\})\s*(?:</function>|$)", re.DOTALL)
        calls = []
        for j, m in enumerate(pat.finditer(gen)):
            try:
                json.loads(m.group(2))
            except json.JSONDecodeError:
                continue
            calls.append({
                "id": f"salvaged_{j}",
                "type": "function",
                "function": {"name": m.group(1), "arguments": m.group(2)},
            })
        if not calls:
            return None
        return {"choices": [{"message": {"content": "", "tool_calls": calls}}], "usage": {}}

    @staticmethod
    def _retry_after(resp) -> float:
        hdr = resp.headers.get("retry-after")
        if hdr:
            try:
                return min(float(hdr) + 1, 65)
            except ValueError:
                pass
        # Groq: "try again in 12.3s"; Gemini: "retryDelay": "30s"
        m = re.search(r"try again in ([\d.]+)s", resp.text) or re.search(
            r'retryDelay"?:\s*"?([\d.]+)s', resp.text)
        return min(float(m.group(1)) + 1, 65) if m else 30.0

