def _approx_chars(messages: list[dict]) -> int:
    total = 0
    for m in messages:
        total += len(m.get("content") or "")
        for tc in m.get("tool_calls") or []:
            total += len(tc["function"]["arguments"])
    return total


def _trim_history(messages: list[dict]) -> None:
    # Truncate the oldest large tool results first; never touch the task message.
    for m in messages[1:]:
        if _approx_chars(messages) <= CHAR_BUDGET:
            return
        if m["role"] == "tool" and len(m["content"]) > 400:
            m["content"] = m["content"][:400] + "\n...[trimmed to fit context]"


