            "id": tc.id,
            "type": "function",
            "function": {"name": tc.name, "arguments": json.dumps(tc.arguments)},
        }
        for tc in resp.tool_calls
    ]
    msg = {"role": "assistant", "content": resp.text or ""}
    if tool_calls:
        msg["tool_calls"] = tool_calls
    return msg


