    def complete(self, system: str, messages: list[dict], tools: list[dict]) -> LLMResponse:
        from ..agent.tool_schemas import anthropic_tools

        payload = {
            "model": self.model,
            "max_tokens": self.max_tokens,
            "system": [{"type": "text", "text": system, "cache_control": {"type": "ephemeral"}}],
            "tools": anthropic_tools(),
            "messages": self._translate(messages),
        }
        headers = {
            "x-api-key": self.api_key,
            "anthropic-version": "2023-06-01",
            "content-type": "application/json",
        }
        resp = requests.post(
            "https://api.anthropic.com/v1/messages",
            headers=headers,
            data=json.dumps(payload),
            timeout=self.timeout,
        )
        if resp.status_code >= 400:
            raise RuntimeError(f"anthropic API error {resp.status_code}: {resp.text[:500]}")
        data = resp.json()

        text_parts, calls = [], []
        for block in data.get("content", []):
            if block["type"] == "text":
                text_parts.append(block["text"])
            elif block["type"] == "tool_use":
                calls.append(ToolCall(id=block["id"], name=block["name"], arguments=block.get("input", {})))
        usage = data.get("usage", {})
        return LLMResponse(
            text="\n".join(text_parts),
            tool_calls=calls,
            input_tokens=usage.get("input_tokens", 0),
            output_tokens=usage.get("output_tokens", 0),
        )

