def prepare_clone(clone_url: str, key: str, base_sha: str | None, branch: str) -> Path:
    """Clone (or reuse) the repo, reset to base_sha or origin/<branch>, make work branch."""
    CLONES_DIR.mkdir(parents=True, exist_ok=True)
    dest = CLONES_DIR / key
    if not (dest / ".git").exists():
        res = run(["git", "clone", clone_url, str(dest)], cwd=CLONES_DIR, timeout=600)
        if not res.ok:
            raise RuntimeError(f"clone failed: {res.combined()}")
    else:
        run(["git", "fetch", "origin"], cwd=dest, timeout=300)

    run(["git", "reset", "--hard"], cwd=dest)
    run(["git", "clean", "-fd"], cwd=dest)
    if base_sha:
        res = run(["git", "checkout", "-f", base_sha], cwd=dest)
        if not res.ok:
            raise RuntimeError(f"checkout {base_sha} failed: {res.combined()}")
    else:
        run(["git", "checkout", "-f", branch], cwd=dest)
        run(["git", "reset", "--hard", f"origin/{branch}"], cwd=dest)
    return dest


def make_work_branch(repo_path: Path, name: str) -> None:
    run(["git", "checkout", "-B", name], cwd=repo_path)


def _build_tree(root: Path, max_entries: int = 600) -> list[str]:
    lines: list[str] = []
    for path in sorted(root.rglob("*")):
        if any(part in _SKIP_DIRS for part in path.relative_to(root).parts):
            continue
        if path.is_dir():
            continue
        if path.suffix not in (".go", ".md", ".mod", ".yaml", ".yml"):
            continue
        lines.append(str(path.relative_to(root)).replace("\\",

      if path.is_dir():
            continue
        if path.suffix not in (".go", ".md", ".mod", ".yaml", ".yml"):
            continue
        lines.append(str(path.relative_to(root)).replace("\\", "/"))
        if len(lines) >= max_entries:
            lines.append("... (truncated)")
            break
    return lines


def repo_map(ctx, path: str | None = None, with_symbols: bool = True) -> str:
    root = ctx.repo_path if not path else (ctx.repo_path / path)
    if not root.exists():
        return f"ERROR: path not found: {path}"
    files = _build_tree(root)
    out = [f"# Repo map ({len(files)} files shown)\n"]
    out.extend(files)
    if with_symbols:
        out.append("\n# Top-level symbols (func/type) per Go file")
        shown = 0
        for rel in files:
            if not rel.endswith(".go") or shown >= 60:
                continue
            try:
                text = (root / rel).read_text(encoding="utf-8", errors="ignore")
            except Exception:
                continue
            syms = [m.group(0).strip() for m in _SYMBOL_RE.finditer(text)]
            if syms:
                out.append(f"\n## {rel}")
                out.extend(f"  {s}" for s in syms[:25])
                shown += 1
    return "\n".join(out)

