def _issue_number(ref: str) -> int:
    m = re.search(r"(\d+)\s*$", str(ref).strip().rstrip("/"))
    if not m:
        raise ValueError(f"Could not parse an issue number from {ref!r}")
    return int(m.group(1))


def _owner_repo(clone_url: str) -> tuple[str, str]:
    m = re.search(r"github\.com[/:]([^/]+)/([^/.]+)", clone_url)
    if not m:
        raise ValueError(f"Cannot derive owner/repo from {clone_url}")
    return m.group(1), m.group(2)


